(() => {
 'use strict';
 const $=id=>document.getElementById(id), api=window.BemoAccount;
 let lang=new URL(location.href).searchParams.get('lang')==='en'?'en':'ar', owner='', catalog=null, selected=null, variant=null, page=0, busy=false, generation=0, mediaGeneration=0, productDraftId=null, variantDraftId=null, stockRequest=null;
 const words={skip:['انتقل إلى المحتوى','Skip to content'],development:['منتجاتك ومخزونك · تابع الطلبات من مساحة الطلبات.','Manage real products · Track orders from the orders workspace.'],account:['حسابي','My account'],kicker:['مساحة البائع','SELLER SPACE'],title:['إدارة متجري','Manage my store'],refresh:['تحديث البيانات','Refresh'],gateTitle:['ابدأ بحسابك ومتجرك','Start with your account and store'],gateCopy:['سجّل الدخول وأكمل ملفك وأنشئ متجرك لتتمكن من إدارة المنتجات.','Sign in, complete your profile, and create your store to manage products.'],deliveryTitle:['سعر توصيل متجرك','Your delivery price'],deliveryCopy:['يُضاف هذا المبلغ مرة واحدة إلى طلب العميل من متجرك. ضع صفراً للتوصيل المجاني. تُثبّت العملة بعد إضافة أول متغير منتج.','This amount applies once per order from your store. Use zero for free delivery. Currency is locked after your first product variant.'],currency:['العملة','Currency'],deliveryFee:['سعر التوصيل','Delivery price'],saveDelivery:['حفظ سعر التوصيل','Save delivery price'],products:['منتجاتي','My products'],newProduct:['إضافة منتج','Add product'],previous:['السابق','Previous'],next:['التالي','Next'],editProduct:['تفاصيل المنتج','Product details'],productTitle:['اسم المنتج','Product name'],description:['وصف المنتج','Description'],category:['التصنيف','Category'],home:['المنزل','Home'],fashion:['الأزياء','Fashion'],electronics:['الإلكترونيات','Electronics'],beauty:['الجمال','Beauty'],sports:['الرياضة','Sports'],other:['أخرى','Other'],saveProduct:['حفظ تفاصيل المنتج','Save product details'],variants:['الخيارات والأسعار','Variants and prices'],variantCopy:['أضف خياراً أساسياً للمنتج أو خيارات مثل اللون والمقاس. لكل خيار رمز مختلف داخل متجرك.','Add a base variant or options such as color and size. Each has a unique SKU within your store.'],sku:['رمز SKU','SKU'],variantLabel:['الخيار (مثال: أحمر / كبير)','Variant (e.g. red / large)'],price:['السعر','Price'],variantEnabled:['الخيار متاح للبيع','Variant enabled'],saveVariant:['حفظ الخيار','Save variant'],addVariant:['خيار جديد','New variant'],stockTitle:['تعديل المخزون','Adjust stock'],variant:['الخيار','Variant'],adjustment:['التغيير في الكمية (+ إضافة / − إزالة)','Quantity change (+ add / − remove)'],reason:['سبب التعديل','Adjustment reason'],saveStock:['حفظ حركة المخزون','Save stock adjustment'],photos:['صور المنتج','Product images'],photoCopy:['حتى 10 صور. اختر JPEG أو PNG أو WebP بحجم لا يتجاوز 10 ميغابايت. تُجهّز الصورة قبل رفعها.','Up to 10 images. Choose JPEG, PNG or WebP up to 10 MB. Images are prepared before upload.'],imageFile:['الصورة','Image'],altText:['وصف الصورة','Image description'],upload:['رفع الصورة','Upload image'],publication:['ظهور المنتج','Product visibility'],publishCopy:['احفظ خياراً بسعر وصورة واحدة على الأقل قبل النشر. الأرشفة توقف ظهور المنتج وتحتفظ بسجلاته.','Save a priced variant and at least one image before publishing. Archiving hides the product and retains its records.'],publish:['نشر المنتج','Publish product'],hide:['إخفاء المنتج','Hide product'],archive:['أرشفة المنتج','Archive product'],footer:['عالم من الاكتشافات الجميلة.','A world of good finds.'],loading:['جارٍ تحميل بيانات المتجر…','Loading your store…'],saving:['جارٍ حفظ التغييرات…','Saving changes…'],saved:['تم الحفظ.','Saved.'],empty:['لم تضف منتجات بعد. ابدأ بمنتجك الأول.','No products yet. Add your first product.'],edit:['تعديل','Edit'],remove:['إزالة','Remove'],stock:['المخزون','Stock'],pending:['بانتظار اكتمال الرفع','Upload pending'],DRAFT:['مسودة','Draft'],ACTIVE:['منشور','Published'],HIDDEN_BY_OWNER:['مخفي','Hidden'],ARCHIVED:['مؤرشف','Archived'],SUSPENDED:['معلّق','Suspended'],settingsFirst:['احفظ العملة وسعر التوصيل أولاً.','Save your currency and delivery price first.']};
 const errors={VERSION_CONFLICT:['تغيّرت البيانات منذ فتحها. حدّثها قبل إعادة التعديل.','Data changed since you opened it. Refresh before editing again.'],SKU_TAKEN:['رمز SKU مستخدم في متجرك. اختر رمزاً آخر.','This SKU is already in your store. Choose another.'],INSUFFICIENT_STOCK:['الكمية التي تحاول إزالتها تتجاوز المخزون المتاح.','The removal exceeds available stock.'],CURRENCY_LOCKED:['لا يمكن تغيير العملة بعد إضافة خيارات المنتجات.','Currency cannot change after product variants exist.'],PRODUCT_IMAGE_REQUIRED:['أضف صورة مكتملة واحدة على الأقل قبل النشر أو إزالة الصورة الأخيرة.','Keep at least one uploaded image before publishing or removing the last image.'],VARIANT_REQUIRED:['أضف خياراً متاحاً بسعر قبل النشر.','Add an enabled, priced variant before publishing.'],MEDIA_INVALID:['تعذّر تجهيز الصورة. اختر JPEG أو PNG أو WebP أصغر من 10 ميغابايت.','Could not prepare this image. Choose JPEG, PNG or WebP smaller than 10 MB.'],MEDIA_LIMIT:['وصلت إلى الحد الأقصى: 10 صور. أزل صورة أولاً.','You reached 10 images. Remove an image first.'],SESSION_CHANGED:['تغيّر الحساب. افتح حسابك مجدداً قبل المتابعة.','Your account changed. Open your account again before continuing.'],AUTH_REQUIRED:['سجّل الدخول أولاً.','Sign in first.'],AMOUNT_INVALID:['أدخل مبلغاً صحيحاً وفق منازل العملة، دون فواصل آلاف.','Enter a valid amount with the currency’s decimal places, without thousands separators.'],STOCK_INVALID:['أدخل تغيراً صحيحاً غير صفري في الكمية وسبباً واضحاً.','Enter a non-zero whole quantity change and a reason.'],fallback:['تعذّر تأكيد العملية. حدّث البيانات قبل إعادة المحاولة لتجنب تكرارها.','The operation could not be confirmed. Refresh before retrying to avoid duplicates.']};
 const t=k=>(words[k]||[k,k])[lang==='ar'?0:1];
 function error(code){$('merchantError').textContent=(errors[code]||errors.fallback)[lang==='ar'?0:1];$('merchantError').hidden=false;$('merchantError').focus();}
 function localize(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.title=t('title')+' — BEMO';document.querySelectorAll('[data-t]').forEach(n=>n.textContent=t(n.dataset.t));$('languageButton').textContent=lang==='ar'?'English':'العربية';$('accountLink').href='account.html?lang='+lang;$('gateLink').href='account.html?lang='+lang+'#store';}
 const digits=()=>catalog?.currencies.find(c=>c.code===catalog.settings?.currency)?.minor_digits??2;
 function amount(text,places){const normalized=String(text).trim().replace(/[٠-٩]/g,c=>String(c.charCodeAt(0)-1632)).replace(/[۰-۹]/g,c=>String(c.charCodeAt(0)-1776)).replace('٫','.');if(!/^\d+(\.\d+)?$/.test(normalized))throw {code:'AMOUNT_INVALID'};const [whole,decimal='']=normalized.split('.');if(decimal.length>places)throw {code:'AMOUNT_INVALID'};const value=BigInt(whole)*10n**BigInt(places)+BigInt(decimal.padEnd(places,'0')||'0');if(value>999999999999n)throw {code:'AMOUNT_INVALID'};return Number(value);}
 const decimal=(minor,places=digits())=>(Number(minor)/10**places).toFixed(places);
 const input=(form,name)=>$(form).elements.namedItem(name);
 async function rpc(name,args){const r=await api.merchantRequest(name,args);if(r.error)throw r.error;return r.data;}
 function lock(value){busy=value;document.querySelectorAll('#merchantWorkspace button,#merchantWorkspace input,#merchantWorkspace textarea,#merchantWorkspace select,#refreshButton').forEach(n=>n.disabled=value);if(!value&&catalog){$('currency').disabled=!!catalog.products.some(p=>p.variants.length)||!!catalog.settings&&catalog.total>0;$('previousProducts').disabled=page===0;$('nextProducts').disabled=(page+1)*24>=catalog.total;}}
 async function act(work){if(busy)return;const ticket=generation;lock(true);$('merchantError').hidden=true;$('merchantStatus').textContent=t('saving');try{const scope=api.merchantScope();const request=async(name,args)=>{const r=await scope.request(name,args);if(r.error)throw r.error;return r.data;};await work(request,scope.media);if(ticket!==generation)return;$('merchantStatus').textContent=t('saved');}catch(e){if(ticket===generation){error(e.code);$('merchantStatus').textContent='';}}finally{if(ticket===generation)lock(false);}}
 async function reload(){const ticket=generation;const result=await rpc('bemo_merchant_catalog',{limit_count:24,offset_count:page*24});if(ticket!==generation)return;catalog=result;renderCatalog();if(selected){const next=catalog.products.find(p=>p.id===selected.id);if(next)openProduct(next,false);else closeEditor();}}
 function node(tag,text,className){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(className)n.className=className;return n;}
 function button(text,action){const b=node('button',text,'secondary-button');b.type='button';b.addEventListener('click',action);return b;}
 function renderCatalog(){
  $('shopName').textContent=catalog.store.title;$('merchantWorkspace').hidden=false;$('merchantGate').hidden=true;$('refreshButton').hidden=false;
  $('currency').replaceChildren(...catalog.currencies.map(c=>{const o=node('option',c.code);o.value=c.code;return o;}));$('currency').value=catalog.settings?.currency||'IQD';
  $('deliveryFee').value=catalog.settings?decimal(catalog.settings.delivery_fee_minor,digits()):'';
  $('productCount').textContent=catalog.total?String(catalog.total):t('empty');$('merchantProducts').replaceChildren();
  for(const p of catalog.products){const card=node('article',undefined,'merchant-product');const copy=node('div');copy.append(node('h3',p.title),node('p',t(p.status)+' · '+p.variants.length+' '+t('variants')));card.append(copy,button(t('edit'),()=>{if(!busy)openProduct(p)}));$('merchantProducts').append(card);}
  $('productPage').textContent=String(page+1);lock(busy);
 }
 function closeEditor(){selected=null;variant=null;productDraftId=null;mediaGeneration++;$('productEditor').hidden=true;$('productForm').reset();$('variantForm').reset();$('stockForm').reset();$('mediaForm').reset();$('variantList').replaceChildren();$('mediaList').replaceChildren();}
 function openProduct(p,focus=true){selected=p;variant=null;variantDraftId=crypto.randomUUID();productDraftId=p?.id||crypto.randomUUID();$('productEditor').hidden=false;$('savedProductTools').hidden=!p;input('productForm','title').value=p?.title||'';input('productForm','description').value=p?.description||'';input('productForm','category').value=p?.category||'other';$('variantForm').reset();if(p){renderVariants();loadMedia(p.id);}if(focus){$('editorTitle').focus();$('productEditor').scrollIntoView({block:'start',behavior:'smooth'});}}
 function renderVariants(){
  $('variantList').replaceChildren();$('stockVariant').replaceChildren();
  for(const v of selected.variants){const row=node('div',undefined,'variant-row');const copy=node('div');copy.append(node('strong',v.sku+' · '+v.label),node('p',decimal(v.price_minor)+' '+v.currency+' · '+t('stock')+': '+v.stock_on_hand));row.append(copy,button(t('edit'),()=>{if(busy)return;variant=v;input('variantForm','sku').value=v.sku;input('variantForm','label').value=v.label;input('variantForm','price').value=decimal(v.price_minor);input('variantForm','active').checked=v.active;input('variantForm','sku').focus();}));$('variantList').append(row);const option=node('option',v.sku+' · '+v.label+' ('+v.stock_on_hand+')');option.value=v.id;$('stockVariant').append(option);}
 }
 async function loadMedia(productId){const ticket=++mediaGeneration,identity=generation;$('mediaList').replaceChildren();try{const rows=await rpc('bemo_merchant_media',{product_id:productId});if(ticket!==mediaGeneration||identity!==generation)return;for(const m of rows){const figure=node('figure'),caption=node('figcaption',m.alt_text+(m.status==='PENDING'?' · '+t('pending'):''));figure.append(caption,button(t('remove'),()=>act(async()=>{await rpc('bemo_finish_media',{media_id:m.id,remove_media:true});await loadMedia(productId);})));$('mediaList').append(figure);if(m.status==='READY'){const result=await api.merchantMedia('preview',m.storage_key);if(ticket!==mediaGeneration||identity!==generation)return;if(result.data){const image=node('img');image.alt=m.alt_text;image.src=result.data.url;figure.prepend(image);}}}}catch(e){if(ticket===mediaGeneration&&identity===generation)error(e.code);}}
 async function prepareImage(file){if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10485760||file.size<1)throw {code:'MEDIA_INVALID'};let image;try{image=await createImageBitmap(file);if(image.width*image.height>40000000)throw {code:'MEDIA_INVALID'};const scale=Math.min(1,1600/Math.max(image.width,image.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.85));if(!blob||blob.size>5242880)throw {code:'MEDIA_INVALID'};return blob;}catch(_){throw {code:'MEDIA_INVALID'}}finally{image?.close();}}
 $('settingsForm').addEventListener('submit',e=>{e.preventDefault();act(async(request,media)=>{const code=$('currency').value;await request('bemo_save_store_settings',{fee:amount($('deliveryFee').value,catalog.currencies.find(c=>c.code===code).minor_digits),currency_code:code,expected_version:catalog.settings?.version||0});await reload();});});
 $('newProduct').addEventListener('click',()=>{if(!catalog.settings){$('merchantStatus').textContent=t('settingsFirst');$('deliveryFee').focus();return;}openProduct(null);});
 $('productForm').addEventListener('submit',e=>{e.preventDefault();act(async(request,media)=>{const p=await request('bemo_save_product',{product_id:productDraftId,title:input('productForm','title').value,description:input('productForm','description').value,category:input('productForm','category').value,expected_version:selected?.version||0});selected={...p,variants:selected?.variants||[]};page=0;await reload();});});
 $('variantForm').addEventListener('submit',e=>{e.preventDefault();act(async(request,media)=>{await request('bemo_save_variant',{product_id:selected.id,variant_id:variant?.id||variantDraftId,sku:input('variantForm','sku').value,label:input('variantForm','label').value,price_minor:amount(input('variantForm','price').value,digits()),enabled:input('variantForm','active').checked,expected_version:variant?.version||0});variant=null;await reload();});});
 $('clearVariant').addEventListener('click',()=>{variant=null;variantDraftId=crypto.randomUUID();$('variantForm').reset();});
 $('stockForm').addEventListener('submit',e=>{e.preventDefault();act(async(request,media)=>{const v=selected.variants.find(v=>v.id===$('stockVariant').value),delta=Number(input('stockForm','delta').value),reason=input('stockForm','reason').value.trim();if(!v||!Number.isInteger(delta)||delta===0||Math.abs(delta)>1000000000||reason.length<3)throw {code:'STOCK_INVALID'};const signature=JSON.stringify([v.id,delta,reason,v.stock_version]);if(stockRequest?.signature!==signature)stockRequest={signature,id:crypto.randomUUID()};await request('bemo_adjust_stock',{variant_id:v.id,delta,reason,request_id:stockRequest.id,expected_version:v.stock_version});stockRequest=null;$('stockForm').reset();await reload();});});
 $('mediaForm').addEventListener('submit',e=>{e.preventDefault();act(async(request,media)=>{const ticket=generation,pid=selected.id;const image=await prepareImage(input('mediaForm','file').files[0]);if(ticket!==generation)throw {code:'SESSION_CHANGED'};const m=await request('bemo_prepare_media',{product_id:pid,media_id:crypto.randomUUID(),alt_text:input('mediaForm','alt').value.trim()});const result=await media('upload',m.storage_key,image);if(result.error)throw result.error;await request('bemo_finish_media',{media_id:m.id,remove_media:false});$('mediaForm').reset();await loadMedia(pid);});});
 for(const [id,status] of [['publishProduct','ACTIVE'],['hideProduct','HIDDEN_BY_OWNER'],['archiveProduct','ARCHIVED']])$(id).addEventListener('click',()=>act(async(request,media)=>{await request('bemo_product_status',{product_id:selected.id,new_status:status,expected_version:selected.version});await reload();}));
 $('refreshButton').addEventListener('click',()=>act(reload));$('previousProducts').addEventListener('click',()=>act(async(request,media)=>{page=Math.max(0,page-1);closeEditor();await reload();}));$('nextProducts').addEventListener('click',()=>act(async(request,media)=>{page++;closeEditor();await reload();}));
 $('languageButton').addEventListener('click',()=>{lang=lang==='ar'?'en':'ar';const url=new URL(location.href);url.searchParams.set('lang',lang);history.replaceState(null,'',url.pathname+url.search);localize();if(catalog){renderCatalog();if(selected)renderVariants();}});
 localize();api.subscribe(state=>{
  const next=state.phase==='ready'?state.identity?.email||'':'';
  if(next!==owner){owner=next;generation++;catalog=null;closeEditor();$('merchantProducts').replaceChildren();$('shopName').textContent='';$('settingsForm').reset();$('merchantWorkspace').hidden=true;$('refreshButton').hidden=true;$('merchantError').hidden=true;busy=false;page=0;stockRequest=null;}
  if(state.phase==='ready'&&state.store&&owner&&!catalog&&!busy){$('merchantStatus').textContent=t('loading');act(reload);}
  else if(['guest','onboarding','blocked','error'].includes(state.phase)||(state.phase==='ready'&&!state.store)){$('merchantGate').hidden=false;$('merchantStatus').textContent='';}
  else if(state.phase==='loading')$('merchantStatus').textContent=t('loading');
 });api.initialize();
})();
